import { type SQL, sql } from "drizzle-orm";
import { date, type PgColumn, timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Conventions for every table:
 * - uuid primary keys, generated by Postgres; snake_case column names written out explicitly;
 * - every constraint and index has a short explicit name (Postgres truncates names over 63 chars,
 *   which would make drizzle-kit regenerate them forever);
 * - no Postgres enums: text columns typed in TypeScript plus CHECK constraints built from the same
 *   arrays, so adding a value is a one-line migration;
 * - timestamps are timestamptz; calendar dates (survey weeks, months) are `date` read as strings.
 */

export const pk = () => uuid("id").primaryKey().defaultRandom();

export const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const createdAt = () => tstz("created_at").notNull().defaultNow();
export const updatedAt = () =>
  tstz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** A survey week, identified by its Monday (IST calendar date), e.g. "2026-10-26". */
export const weekStart = (name = "week_start") => date(name, { mode: "string" });

/** `col in ('a', 'b')` for CHECK constraints. Values are trusted constants from code. */
export function inList(column: PgColumn, values: readonly string[]): SQL {
  for (const v of values) if (!/^[a-z0-9_]+$/i.test(v)) throw new Error(`Unsafe CHECK value: ${v}`);
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

/** CHECK that a date column is a Monday. */
export const isMonday = (column: PgColumn): SQL => sql`extract(isodow from ${column}) = 1`;

export const SHA256_HEX = sql.raw(`'^[0-9a-f]{64}$'`);
